def handle_prompt(text, tenant_policy):
    if "sk-" in text or "password=" in text.lower():
        return {"action": "block", "reason": "possible secret"}
    redacted = text.replace("student@example.com", "[email]")
    audit = {
        "policy": tenant_policy,
        "pii_action": "redacted" if redacted != text else "none",
        "store_raw": False,
    }
    return {"action": "send_to_model", "text": redacted, "audit": audit}
print(handle_prompt("email student@example.com", "school-privacy-v2"))
